import Foundation
import Testing
@testable import ParseAPI
@Test func ipDeepExpansion() throws {let decoder=JSONDecoder();decoder.keyDecodingStrategy = .convertFromSnakeCase;let value=try decoder.decode(IP.self,from:Data(#"{"ip":"198.51.100.10","country":"XX","country_name":"Example","continent":"NA","asn":"AS64512","asn_name":"Fixture","city":"Example","state":"EX","state_name":"Example state","postal":"00123","latitude":0,"longitude":-0.000001,"timezone":"Etc/UTC","network":"198.51.100.0/24","asn_type":"education","registry":"arin","datacenter":false,"relay":false,"tor":false,"vpn":false,"proxy":false,"provider":null}"#.utf8));let d=value;#expect(d.latitude==0 && d.longitude == -0.000001 && d.postal=="00123" && d.proxy==false && d.stateName=="Example state" && d.timezone=="Etc/UTC" && d.network=="198.51.100.0/24" && d.asnType=="education");for text in [#"{"ip":"198.51.100.10"}"#,#"{"ip":"198.51.100.10"}"#,#"{"ip":"198.51.100.10","latitude":null,"longitude":null,"proxy":null}"#]{let old=try decoder.decode(IP.self,from:Data(text.utf8));#expect(old.latitude==nil && old.proxy==nil)}}
